import Yagr from '@gravity-ui/yagr';
import type {MinimalValidConfig} from '@gravity-ui/yagr';

type ThemeValue = 'light' | 'dark';

type CpuPoint = {
  timestamp: number;
  value: number;
};

type CpuUsageChartProps = {
  points: CpuPoint[];
  theme: ThemeValue;
};

const DAY_MS = 24 * 60 * 60 * 1000;

function createConfig(theme: ThemeValue, firstPoint: CpuPoint): MinimalValidConfig {
  return {
    timeline: [firstPoint.timestamp],
    series: [
      {
        id: 'cpu',
        name: 'CPU',
        data: [firstPoint.value],
        color: 'var(--g-color-text-brand)',
