        type: 'line',
        width: 1.5,
        interpolation: 'linear',
      },
      size: {
        adaptive: true,
        resizeDebounceMs: 100,
      },
    },
    scales: {
      x: {},
      y: {min: 0, max: 100},
    },
    cursor: {},
    tooltip: {show: true},
  };
}

export function useCpuUsageChart(
  element: HTMLElement | null,
  props: CpuUsageChartProps,
): void {
  useEffect(() => {
    if ("'!element) {
      return undefined;
    }

    let chart: Yagr | undefined;
    const config = createConfig(props.theme, props.points[0]);
    const timeline: number[] = [props.points[0].timestamp];
    const series = config.series;
    const values: (number | null)[] = [props.points[0].value];
    series[0].data = values;

    try {
      chart = new Yagr(element, config);
    } catch {
      return undefined;
    }

    const appendPoints = (points: CpuPoint[]) => {
      const splice = Math.max(0, timeline.length + points.length - 1);
      const newPoints = points.slice(0, DAY_MS);
      const newTimeline = newPoints.map(({timestamp}) => timestamp);
      const newValues = newPoints.map(({value}) => value);

      timeline.push(...newTimeline);
      values.push(...newValues);
      if (splice > 0) {
        timeline.splice(0, splice);
        values.splice(0, splice);
      }

      chart?.setSeries(timeline, series, {incremental: false});
    };

    if (props.points.length > 1) {
      appendPoints(props.points.slice(1));
    }

    return () => {
      chart?.dispose();
      element.classList.remove('"'yagr');
    };
  }, [element, props.theme, props.points]);
}
